UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "All": {
        "Claimed": "select task.name_ as \\"Stage\\", cuser.vcemailid as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.time_ ELSE null END as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Rule Name\\", null as \\"Alert closed date and time (42 CS Agent)\\", null as \\"Statused By User ID (42 CS Agent)\\",CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)-> 0  -> ''txn'' ->''attribs''->''pismo_raw''->''fields''->> ''card_id'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) -> ''txn'' ->''attribs''->''pismo_raw''->''fields''->> ''card_id'' END as \\"VPA\\" , class.text_ as \\"Class\\", acc.text_ as \\"Account\\", null as \\"Document Number\\", lastfour.text_ as \\"Last 4 digits of card\\", cusname.text_ as \\"Customer Name\\", authdate.text_ as \\"Authorization Date IST\\", authtime.text_ as \\"Authorization Timestamp IST\\", scr.text_ as \\"FRM Score\\", netscr.text_ as \\"Network Score\\", arc.text_ as \\"Authorization Response Code\\", ad.text_ as \\"Approved/Declined\\", posmode.text_ as \\"POS Entry Mode\\", card.text_ as \\"Card Present/Card Not Present\\", mcc.text_ as \\"Merchant Category Code (MCC)\\", mname.text_ as \\"Merchant Name\\", mloc.text_ as \\"Merchant Location\\", ccc.text_ as \\"Card Acceptor Country Code\\", accc.text_ as \\"Acquirer Country Code\\", mcr.text_ as \\"MOTO/ECI/Recurring\\", icc.text_ as \\"Issuer Currency Code\\", CASE WHEN ( CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN (cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) -> 0 -> ''txn'' -> ''attribs'' -> ''pismo_raw'' -> ''fields'' ->> ''bin'')::BIGINT ELSE (cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) -> ''txn'' -> ''attribs'' -> ''pismo_raw'' -> ''fields'' ->> ''bin'')::BIGINT END ) IN (53186547, 53186539) THEN rrn.text_ ELSE NULL END AS \\"Retrieval Reference Number (For USFB Mastercard)\\", CASE WHEN ( CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN (cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) -> 0 -> ''txn'' -> ''attribs'' -> ''pismo_raw'' -> ''fields'' ->> ''bin'')::BIGINT ELSE (cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) -> ''txn'' -> ''attribs'' -> ''pismo_raw'' -> ''fields'' ->> ''bin'')::BIGINT END ) NOT IN (53186547, 53186539) THEN rrn.text_ ELSE NULL END AS \\"Retrieval Reference Number (For CUB,USFB,ESAF,SSFB Rupay)\\", txnid.text_ as \\"Transaction ID\\", caid.text_ as \\"Card Acceptor ID\\", agentname.text_ as \\"Agent Name\\", firstclaim.text_ as \\"First claimed Date and Time\\", firstunclaim.text_ as \\"Pending Status Date and Time\\", comm.text_ as \\"Comments\\", actiontaken.text_ as \\"Action Taken by RA or Status\\", ruletrig.text_ as \\"Rule Type\\", agentstat.text_ as \\"Agent Status\\"  from camunda.act_hi_procinst hiproinst left join camunda.act_ru_task task on hiproinst.proc_inst_id_ = task.proc_inst_id_ left join camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_ LEFT JOIN ui.webuser cuser ON cuser.iuserid = CAST(task.assignee_ AS INTEGER) left join camunda.act_hi_detail oplog on oplog.id_ = ( select id_ from camunda.act_hi_detail where proc_inst_id_ = task.proc_inst_id_ and name_ = ''userActivity'' order by time_ desc limit 1 ) left join camunda.act_ru_variable payer on payer.proc_inst_id_ = task.proc_inst_id_ and payer.name_ = ''payer'' left join camunda.act_ru_variable payee on payee.proc_inst_id_ = task.proc_inst_id_ and payee.name_ = ''payee'' left join camunda.act_ru_variable TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' left join camunda.act_ru_variable TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' left join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' left join camunda.act_hi_varinst Txn on Txn.proc_inst_id_ = task.proc_inst_id_ and Txn.name_ = ''Transaction'' left join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ left join camunda.act_hi_varinst class on class.proc_inst_id_ = hiproinst.proc_inst_id_ and class.name_ = ''TransactionClass'' left join camunda.act_hi_varinst acc on acc.proc_inst_id_ = hiproinst.proc_inst_id_ and acc.name_ = ''accountid'' left join camunda.act_hi_varinst lastfour on lastfour.proc_inst_id_ = hiproinst.proc_inst_id_ and lastfour.name_ = ''lastfourdigit'' left join camunda.act_hi_varinst cusname on cusname.proc_inst_id_ = hiproinst.proc_inst_id_ and cusname.name_ = ''customerName'' left join camunda.act_hi_varinst authdate on authdate.proc_inst_id_ = hiproinst.proc_inst_id_ and authdate.name_ = ''authDate'' left join camunda.act_hi_varinst authtime on authtime.proc_inst_id_ = hiproinst.proc_inst_id_ and authtime.name_ = ''authTime'' left join camunda.act_hi_varinst scr on scr.proc_inst_id_ = hiproinst.proc_inst_id_ and scr.name_ = ''RiskScore'' left join camunda.act_hi_varinst netscr on netscr.proc_inst_id_ = hiproinst.proc_inst_id_ and netscr.name_ = ''networkScore'' left join camunda.act_hi_varinst arc on arc.proc_inst_id_ = hiproinst.proc_inst_id_ and arc.name_ = ''authResponseCode'' left join camunda.act_hi_varinst ad on ad.proc_inst_id_ = hiproinst.proc_inst_id_ and ad.name_ = ''approvalStatus'' left join camunda.act_hi_varinst posmode on posmode.proc_inst_id_ = hiproinst.proc_inst_id_ and posmode.name_ = ''posEntryMode'' left join camunda.act_hi_varinst card on card.proc_inst_id_ = hiproinst.proc_inst_id_ and card.name_ = ''cardStatus'' left join camunda.act_hi_varinst mcc on mcc.proc_inst_id_ = hiproinst.proc_inst_id_ and mcc.name_ = ''mcc'' left join camunda.act_hi_varinst mname on mname.proc_inst_id_ = hiproinst.proc_inst_id_ and mname.name_ = ''merchantname'' left join camunda.act_hi_varinst mloc on mloc.proc_inst_id_ = hiproinst.proc_inst_id_ and mloc.name_ = ''merchantLocation'' left join camunda.act_hi_varinst ccc on ccc.proc_inst_id_ = hiproinst.proc_inst_id_ and ccc.name_ = ''cardAcceptorCountryCode'' left join camunda.act_hi_varinst accc on accc.proc_inst_id_ = hiproinst.proc_inst_id_ and accc.name_ = ''acquirerCountryCode'' left join camunda.act_hi_varinst mcr on mcr.proc_inst_id_ = hiproinst.proc_inst_id_ and mcr.name_ = ''motoEciRecurring'' left join camunda.act_hi_varinst icc on icc.proc_inst_id_ = hiproinst.proc_inst_id_ and icc.name_ = ''issuerCountryCode'' left join camunda.act_hi_varinst rrn on rrn.proc_inst_id_ = hiproinst.proc_inst_id_ and rrn.name_ = ''retrievalReferenceNumber'' left join camunda.act_hi_varinst rrnusfb on rrnusfb.proc_inst_id_ = hiproinst.proc_inst_id_ and rrnusfb.name_ = ''retrievalReferenceNumber'' left join camunda.act_hi_varinst txnid on txnid.proc_inst_id_ = hiproinst.proc_inst_id_ and txnid.name_ = ''transaction_id'' left join camunda.act_hi_varinst caid on caid.proc_inst_id_ = hiproinst.proc_inst_id_ and caid.name_ = ''cardAcceptorId'' left join camunda.act_hi_varinst agentname on agentname.proc_inst_id_ = hiproinst.proc_inst_id_ and agentname.name_ = ''agentName'' left join camunda.act_hi_varinst firstclaim on firstclaim.proc_inst_id_ = hiproinst.proc_inst_id_ and firstclaim.name_ = ''firstClaimDateTime'' left join camunda.act_hi_varinst firstunclaim on firstunclaim.proc_inst_id_ = hiproinst.proc_inst_id_ and firstunclaim.name_ = ''firstUnclaimDateTime'' left join camunda.act_hi_varinst comm on comm.proc_inst_id_ = hiproinst.proc_inst_id_ and comm.name_ = ''lastComment'' left join camunda.act_hi_varinst actiontaken on actiontaken.proc_inst_id_ = hiproinst.proc_inst_id_ and actiontaken.name_ = ''lastDispositionSelected'' left join camunda.act_hi_varinst ruletrig on ruletrig.proc_inst_id_ = hiproinst.proc_inst_id_ and ruletrig.name_ = ''triggeredtype'' left join camunda.act_hi_varinst agentstat on agentstat.proc_inst_id_ = hiproinst.proc_inst_id_ and agentstat.name_ = ''agentStatus'' where date(hiproinst.start_time_) >= :StartDate AND date(hiproinst.start_time_) <= :EndDate   and task.assignee_ is not null and hiproinst.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) and hiproinst.tenant_id_= :tenantidstr limit 25000",
        "Unclaimed": " select task.name_ as \\"Stage\\", cuser.vcemailid as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.time_ ELSE null END as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Rule Name\\", null as \\"Alert closed date and time (42 CS Agent)\\", null as \\"Statused By User ID (42 CS Agent)\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)-> 0  -> ''txn'' ->''attribs''->''pismo_raw''->''fields''->> ''card_id'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) -> ''txn'' ->''attribs''->''pismo_raw''->''fields''->> ''card_id'' END as \\"VPA\\"  ,  class.text_ as \\"Class\\", acc.text_ as \\"Account\\", null as \\"Document Number\\", lastfour.text_ as \\"Last 4 digits of card\\", cusname.text_ as \\"Customer Name\\", authdate.text_ as \\"Authorization Date IST\\", authtime.text_ as \\"Authorization Timestamp IST\\", scr.text_ as \\"FRM Score\\", netscr.text_ as \\"Network Score\\", arc.text_ as \\"Authorization Response Code\\", ad.text_ as \\"Approved/Declined\\", posmode.text_ as \\"POS Entry Mode\\", card.text_ as \\"Card Present/Card Not Present\\", mcc.text_ as \\"Merchant Category Code (MCC)\\", mname.text_ as \\"Merchant Name\\", mloc.text_ as \\"Merchant Location\\", ccc.text_ as \\"Card Acceptor Country Code\\", accc.text_ as \\"Acquirer Country Code\\", mcr.text_ as \\"MOTO/ECI/Recurring\\", icc.text_ as \\"Issuer Currency Code\\", CASE WHEN ( CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN (cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) -> 0 -> ''txn'' -> ''attribs'' -> ''pismo