ionAmount.name_ = ''TransactionAmount'' left join camunda.act_ru_variable TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' left join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' left join camunda.act_hi_varinst Txn on Txn.proc_inst_id_ = task.proc_inst_id_ and Txn.name_ = ''Transaction'' left join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ left join camunda.act_hi_varinst class on class.proc_inst_id_ = hiproinst.proc_inst_id_ and class.name_ = ''TransactionClass'' left join camunda.act_hi_varinst acc on acc.proc_inst_id_ = hiproinst.proc_inst_id_ and acc.name_ = ''accountid'' left join camunda.act_hi_varinst lastfour on lastfour.proc_inst_id_ = hiproinst.proc_inst_id_ and lastfour.name_ = ''lastfourdigit'' left join camunda.act_hi_varinst cusname on cusname.proc_inst_id_ = hiproinst.proc_inst_id_ and cusname.name_ = ''customerName'' left join camunda.act_hi_varinst authdate on authdate.proc_inst_id_ = hiproinst.proc_inst_id_ and authdate.name_ = ''authDate'' left join camunda.act_hi_varinst authtime on authtime.proc_inst_id_ = hiproinst.proc_inst_id_ and authtime.name_ = ''authTime'' left join camunda.act_hi_varinst scr on scr.proc_inst_id_ = hiproinst.proc_inst_id_ and scr.name_ = ''RiskScore'' left join camunda.act_hi_varinst netscr on netscr.proc_inst_id_ = hiproinst.proc_inst_id_ and netscr.name_ = ''networkScore'' left join camunda.act_hi_varinst arc on arc.proc_inst_id_ = hiproinst.proc_inst_id_ and arc.name_ = ''authResponseCode'' left join camunda.act_hi_varinst ad on ad.proc_inst_id_ = hiproinst.proc_inst_id_ and ad.name_ = ''approvalStatus'' left join camunda.act_hi_varinst posmode on posmode.proc_inst_id_ = hiproinst.proc_inst_id_ and posmode.name_ = ''posEntryMode'' left join camunda.act_hi_varinst card on card.proc_inst_id_ = hiproinst.proc_inst_id_ and card.name_ = ''cardStatus'' left join camunda.act_hi_varinst mcc on mcc.proc_inst_id_ = hiproinst.proc_inst_id_ and mcc.name_ = ''mcc'' left join camunda.act_hi_varinst mname on mname.proc_inst_id_ = hiproinst.proc_inst_id_ and mname.name_ = ''merchantname'' left join camunda.act_hi_varinst mloc on mloc.proc_inst_id_ = hiproinst.proc_inst_id_ and mloc.name_ = ''merchantLocation'' left join camunda.act_hi_varinst ccc on ccc.proc_inst_id_ = hiproinst.proc_inst_id_ and ccc.name_ = ''cardAcceptorCountryCode'' left join camunda.act_hi_varinst accc on accc.proc_inst_id_ = hiproinst.proc_inst_id_ and accc.name_ = ''acquirerCountryCode'' left join camunda.act_hi_varinst mcr on mcr.proc_inst_id_ = hiproinst.proc_inst_id_ and mcr.name_ = ''motoEciRecurring'' left join camunda.act_hi_varinst icc on icc.proc_inst_id_ = hiproinst.proc_inst_id_ and icc.name_ = ''issuerCountryCode'' left join camunda.act_hi_varinst rrn on rrn.proc_inst_id_ = hiproinst.proc_inst_id_ and rrn.name_ = ''retrievalReferenceNumber'' left join camunda.act_hi_varinst rrnusfb on rrnusfb.proc_inst_id_ = hiproinst.proc_inst_id_ and rrnusfb.name_ = ''retrievalReferenceNumber'' left join camunda.act_hi_varinst txnid on txnid.proc_inst_id_ = hiproinst.proc_inst_id_ and txnid.name_ = ''transaction_id'' left join camunda.act_hi_varinst caid on caid.proc_inst_id_ = hiproinst.proc_inst_id_ and caid.name_ = ''cardAcceptorId'' left join camunda.act_hi_varinst agentname on agentname.proc_inst_id_ = hiproinst.proc_inst_id_ and agentname.name_ = ''agentName'' left join camunda.act_hi_varinst firstclaim on firstclaim.proc_inst_id_ = hiproinst.proc_inst_id_ and firstclaim.name_ = ''firstClaimDateTime'' left join camunda.act_hi_varinst firstunclaim on firstunclaim.proc_inst_id_ = hiproinst.proc_inst_id_ and firstunclaim.name_ = ''firstUnclaimDateTime'' left join camunda.act_hi_varinst comm on comm.proc_inst_id_ = hiproinst.proc_inst_id_ and comm.name_ = ''lastComment'' left join camunda.act_hi_varinst actiontaken on actiontaken.proc_inst_id_ = hiproinst.proc_inst_id_ and actiontaken.name_ = ''lastDispositionSelected'' left join camunda.act_hi_varinst ruletrig on ruletrig.proc_inst_id_ = hiproinst.proc_inst_id_ and ruletrig.name_ = ''triggeredtype'' left join camunda.act_hi_varinst agentstat on agentstat.proc_inst_id_ = hiproinst.proc_inst_id_ and agentstat.name_ = ''agentStatus'' where date(hiproinst.start_time_) >= :StartDate AND date(hiproinst.start_time_) <= :EndDate  and task.assignee_ is null and hiproinst.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) and hiproinst.tenant_id_= :tenantidstr limit 25000",
